using System;
using System.Collections.Generic;
using System.Text;

namespace Elans.Shared
{
    // Look-alike detection after Unicode's UTS #39 ("Unicode Security Mechanisms", section 4 Confusable Detection), with the
    // confusables data in Confusables.Data.cs (generated by Tools/unicode/make_confusables.py - do not edit that file).
    //
    //   Skeleton(s)  exactly UTS #39: NFD, every code point replaced by its prototype from the table, NFD again. Two strings
    //                with the same skeleton look alike ("pаypal" with a Cyrillic а and "paypal"; "rn" and "m").
    //   NameKey(s)   the key names are made unique by: two names with the same key are "the same name". The skeleton plus
    //                what the Lodge's older fold did: case folded, small capitals as their letter (UTS #39 keeps "ʟ" apart
    //                from "l"), 0->o, 1/i/|/!->l, 3->e, 5->s, and white space and the separators - _ . ' dropped. Never shown.
    //
    // Accents stay: "Élan" and "Elan" have different keys (UTS #39 maps no accent away; the mark is visible).
    public static partial class Confusables
    {
        // the table, unpacked once: sorted source code points and where each target starts in Pool (Offsets[i]..Offsets[i + 1])
        static readonly int[] Sources;
        static readonly int[] Offsets;
        static readonly Dictionary<int, int> Caps;

        // a static constructor runs after every static field initializer of both halves of the class
        static Confusables()
        {
            var n = Deltas.Length;
            if (Lengths.Length != n || n != DataEntries) throw new InvalidOperationException("Confusables: the generated table is inconsistent");
            Sources = new int[n];
            Offsets = new int[n + 1];
            int cp = 0, off = 0;
            for (int i = 0; i < n; i++)
            {
                cp += Deltas[i];
                Sources[i] = cp;
                Offsets[i] = off;
                var l = Lengths[i];
                off += l <= '9' ? l - '0' : l - 'a' + 10;
            }
            Offsets[n] = off;
            if (off != Pool.Length) throw new InvalidOperationException("Confusables: the generated table is inconsistent");
            Caps = new Dictionary<int, int>(SmallCaps.Length / 2);
            for (int i = 0; i + 1 < SmallCaps.Length; i += 2) Caps[SmallCaps[i]] = SmallCaps[i + 1];
        }

        // the prototype of one code point, or null when it is its own
        public static string Prototype(int codePoint)
        {
            var i = Array.BinarySearch(Sources, codePoint);
            return i < 0 ? null : Pool.Substring(Offsets[i], Offsets[i + 1] - Offsets[i]);
        }

        // UTS #39 skeleton: NFD, map each code point to its prototype, NFD again. An invalid (unpaired) surrogate counts as U+FFFD.
        public static string Skeleton(string s)
        {
            if (string.IsNullOrEmpty(s)) return "";
            var d = Nfd(s);
            var sb = new StringBuilder(d.Length + 8);
            foreach (var r in d.EnumerateRunes())
            {
                var p = Prototype(r.Value);
                if (p != null) sb.Append(p); else sb.Append(r.ToString());
            }
            return Nfd(sb.ToString());
        }

        public static bool LookAlike(string a, string b) => string.Equals(Skeleton(a), Skeleton(b), StringComparison.Ordinal);

        // the uniqueness key of a name (see the top). Callers normalize first (the Lodge: Names.Normalize); NFKC is applied here
        // too, so the key is the same either way. Up to 4 rounds until nothing changes: case folding can reveal a further
        // look-alike ("M" -> "m" -> "rn").
        public static string NameKey(string name)
        {
            if (string.IsNullOrEmpty(name)) return "";
            var k = name;
            try { k = name.Normalize(NormalizationForm.FormKC); } catch (ArgumentException) { }
            for (int round = 0; round < 4; round++)
            {
                var next = Fold(Skeleton(k));
                if (next == k) break;
                k = next;
            }
            return k;
        }

        public static bool SameName(string a, string b) => string.Equals(NameKey(a), NameKey(b), StringComparison.Ordinal);

        static string Fold(string s)
        {
            var sb = new StringBuilder(s.Length);
            foreach (var r in s.EnumerateRunes())
            {
                if (Rune.IsWhiteSpace(r) || Rune.IsControl(r)) continue;
                var cat = Rune.GetUnicodeCategory(r);
                if (cat is System.Globalization.UnicodeCategory.Format or System.Globalization.UnicodeCategory.SpaceSeparator) continue;
                var c = Rune.ToLowerInvariant(r).Value;
                if (Caps.TryGetValue(c, out var low)) c = low;
                switch (c)
                {
                    case '-': case '_': case '.': case '\'': continue;
                    case '0': c = 'o'; break;
                    case '1': case 'i': case '|': case '!': c = 'l'; break;
                    case '3': c = 'e'; break;
                    case '5': c = 's'; break;
                }
                sb.Append(char.ConvertFromUtf32(c));
            }
            return sb.ToString();
        }

        static string Nfd(string s)
        {
            try { return s.Normalize(NormalizationForm.FormD); }
            catch (ArgumentException) { return s; }   // invalid surrogates: left as they are (EnumerateRunes reads them as U+FFFD)
        }
    }
}
